const publishDialog=document.createElement('dialog');
publishDialog.id='publish-dialog';publishDialog.setAttribute('aria-labelledby','publish-heading');
publishDialog.innerHTML=`<div class="dialog-head"><span>CREATOR STUDIO</span><button type="button" id="close-publish" aria-label="关闭发布窗口">✕</button></div><h2 id="publish-heading">把你的想法，变成一次互动。</h2><p>先用一个切片，邀请大家进入你的世界。</p><div class="publish-notice">原型体验 · 发布到本机首页，刷新后仍保留；暂不向其他用户公开。</div><form id="publish-form"><div class="publish-grid"><div class="publish-fields"><label>Slice标题 <input name="title" required maxlength="50" placeholder="给你的Slice起个名字"></label><label>一句话介绍 <textarea name="description" required maxlength="160" rows="3" placeholder="用户可以做什么，又会发现什么？"></textarea></label><label>内容分类 <select name="category">${cats.slice(1).map(c=>`<option>${c}</option>`).join('')}</select></label><label>Interactive Slice <select name="template"><option value="beat">节奏挑战 · 点击接住光点</option><option value="orbit">轨道实验 · 拖动调整引力</option><option value="quiz">概率问答 · 做出一个选择</option><option value="wave">波的叠加 · 调整频率</option><option value="draw">对称绘画 · 自由拖动画笔</option><option value="social">超能力选择 · 选你的一边</option></select></label><span class="field-help">这一版从六个可玩的模板开始，暂不支持上传自定义代码。</span><label>Slicer名称 <input name="author" required maxlength="30" value="好奇心Slicer"></label></div><div class="publish-preview"><div class="preview-label">FEED PREVIEW <span>在这里直接试玩</span></div><div id="publish-slice"></div><h3 id="preview-title">你的下一个好想法</h3><p id="preview-desc">写下一句话介绍，让人忍不住试一下。</p><span id="preview-author">好奇心Slicer</span></div></div><p id="publish-error" role="alert"></p><div class="dialog-bottom"><button type="button" id="save-draft">保存草稿</button><button type="submit" class="dark">发布到本机首页 ↗</button></div></form>`;
document.body.append(publishDialog);
const publishForm=document.querySelector('#publish-form');const storageKey='slice-local-works-v1',draftKey='slice-publish-draft-v1';const templates=['beat','orbit','quiz','wave','draw','social'];
function readStored(key,fallback){try{return JSON.parse(localStorage.getItem(key))??fallback}catch{return fallback}}
function formData(){const f=new FormData(publishForm);return {title:String(f.get('title')).trim(),desc:String(f.get('description')).trim(),cat:String(f.get('category')),template:String(f.get('template')),author:String(f.get('author')).trim()}}
function updatePublishPreview(reset=false){const d=formData();document.querySelector('#preview-title').textContent=d.title||'你的下一个好想法';document.querySelector('#preview-desc').textContent=d.desc||'写下一句话介绍，让人忍不住试一下。';document.querySelector('#preview-author').textContent=d.author||'好奇心Slicer';const host=document.querySelector('#publish-slice');if(reset||host.dataset.template!==d.template){host.dataset.template=d.template;const source=works.find(w=>w.id===d.template);host.innerHTML=stage(source);initStages(host)}}
document.querySelector('#publish-entry').onclick=()=>{const d=readStored(draftKey,null);if(d){for(const [name,key] of [['title','title'],['description','desc'],['category','cat'],['template','template'],['author','author']])if(typeof d[key]==='string')publishForm.elements[name].value=d[key]}document.querySelector('#publish-error').textContent='';publishDialog.showModal();updatePublishPreview(true)};
document.querySelector('#close-publish').onclick=()=>publishDialog.close();publishForm.addEventListener('input',()=>updatePublishPreview());
document.querySelector('#save-draft').onclick=()=>{try{localStorage.setItem(draftKey,JSON.stringify(formData()));toast('草稿已保存在本机')}catch{document.querySelector('#publish-error').textContent='浏览器未允许保存，请检查存储设置后重试。'}};
publishForm.onsubmit=e=>{e.preventDefault();const d=formData();if(!d.title||!d.desc||!d.author){document.querySelector('#publish-error').textContent='请填写标题、介绍和Slicer名称，不能只输入空格。';return}const source=works.find(w=>w.id===d.template);const work={...d,id:'local-'+crypto.randomUUID(),local:true,bg:source.bg,time:'本机发布',likes:0,plays:'0'};try{const entries=works.filter(w=>w.local);localStorage.setItem(storageKey,JSON.stringify([work,...entries]));localStorage.removeItem(draftKey)}catch{document.querySelector('#publish-error').textContent='保存失败，Slice尚未发布。请检查浏览器存储空间后重试。';return}works.unshift(work);selected='All';document.querySelectorAll('[data-cat]').forEach(b=>{b.classList.toggle('selected',b.dataset.cat==='All');b.setAttribute('aria-pressed',b.dataset.cat==='All')});render();publishDialog.close();publishForm.reset();document.querySelector('#card-'+work.id).scrollIntoView({behavior:'smooth',block:'center'});toast('已发布到本机首页 · 刷新后仍会保留')};
const saved=readStored(storageKey,[]);if(Array.isArray(saved)){const valid=saved.filter(w=>w&&/^local-[a-z0-9-]+$/.test(w.id)&&templates.includes(w.template)&&cats.slice(1).includes(w.cat)&&['title','desc','author'].every(k=>typeof w[k]==='string')&&/^#[0-9a-f]{6}$/i.test(w.bg)).map(w=>({...w,local:true,likes:0,plays:'0',time:'本机发布'}));works.unshift(...valid);render()}
